 */
export async function loadPlans(ctx: KspecContext): Promise<LoadedPlan[]> {
  const plansPath = getPlansFilePath(ctx);

  try {
    const plans = await loadPlansFromFile(plansPath);
    return plans.map((plan) => ({
      ...plan,
      _sourceFile: plansPath,
    }));
