  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;

  return plans.find(
    (p) =>
      // Match full ULID
      p._ulid === cleanRef ||
      // Match short ULID (prefix)
      p._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()) ||
