		expect(columns).toHaveLength(5);
		expect(columns.map((c) => c.id)).toEqual([
			'backlog',
			'ready',
			'in_progress',
			'review',
			'done'
		]);
	});
});

describe('getStatusClasses', () => {
	// AC: @ui-task-board ac-2
	it('returns correct classes for all known statuses', () => {
		const statuses = [
			'pending',
			'in_progress',
			'pending_review',
			'needs_work',
