				matchedFields: ['title']
			});
		}
	}

	// Search items
	for (const item of snapshot.items) {
		if (
			item.title.toLowerCase().includes(lowerQuery) ||
			item.slugs.some((s) => s.includes(lowerQuery))
		) {
			results.push({
				type: 'item',
				ulid: item._ulid,
