			results.push({
				type: 'inbox',
				ulid: inbox._ulid,
				title: inbox.text.slice(0, 50),
				matchedFields: ['text']
			});
		}
	}

	return {
		results: results.slice(0, 20),
		total: results.length,
		showing: Math.min(results.length, 20)
	};
