function filterTasks(
	tasks: ExportedTask[],
	params?: {
		status?: string;
		tag?: string;
		assignee?: string;
		automation?: string;
	}
): ExportedTask[] {
	let result = tasks;

	if (params?.status) {
		result = result.filter((t) => t.status === params.status);
	}
	if (params?.tag) {
		result = result.filter((t) => t.tags.includes(params.tag!));
	}
	if (params?.assignee) {
		result = result.filter((t) => t.assignee === params.assignee);
	}
	if (params?.automation) {
