 * AC: @ui-session-stream ac-4
 */
export interface SessionDetail extends SessionSummary {
	task_id?: string;
	agent_id?: string;
	trigger?: string;
	spec_context?: SessionSpecContext | null;
	budget?: SessionBudget | null;
}

/**
