/**
 * Static analysis tests for static-mode session messaging.
 *
 * AC: @gh-pages-export ac-22 — sessions routes show informative read-only messaging.
 */

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const SESSION_PAGE = join(
	process.cwd(),
	'packages',
	'web-ui',
	'src',
	'routes',
	'sessions',
	'[id]',
	'+page.svelte'
);

const source = readFileSync(SESSION_PAGE, 'utf-8');

describe('session detail static mode messaging', () => {
	// AC: @gh-pages-export ac-22
	it('shows a dedicated static-mode message instead of only surfacing a fetch error', () => {
		expect(source).toContain("isStaticMode()");
		expect(source).toContain('data-testid="session-static-message"');
		expect(source).toContain('Session history is not included in the static export');
	});
});

