/**
 * Build-output verification for static-mode session messaging.
 *
 * AC: @gh-pages-export ac-22 — sessions routes show informative read-only messaging.
 */

import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const COMPILED_SESSION_PAGE = join(
	process.cwd(),
	'packages',
	'web-ui',
	'.svelte-kit',
	'output',
	'server',
	'entries',
	'pages',
	'sessions',
	'_id_',
	'_page.svelte.js'
);

describe('session detail static mode messaging', () => {
	// AC: @gh-pages-export ac-22
	it('ships the static-mode message in the compiled sessions detail page', () => {
		expect(existsSync(COMPILED_SESSION_PAGE)).toBe(true);
		const compiled = readFileSync(COMPILED_SESSION_PAGE, 'utf-8');
		expect(compiled).toContain('session-static-message');
		expect(compiled).toContain('Session history is not included in the static export');
	});
});

